pub enum Tri { A, B, C }
pub unitary fn ga(q: Q<Unit>) -> Q<Unit> { power(global_phase_eighth,2)(q) }
pub unitary fn gb(q: Q<Unit>) -> Q<Unit> { power(global_phase_eighth,4)(q) }
pub unitary fn gc(q: Q<Unit>) -> Q<Unit> { power(global_phase_eighth,6)(q) }
pub unitary fn choose(s:Q<Tri>,q:Q<Unit>,z:Q<Unit>)->(Q<Tri>,Q<Unit>,Q<Unit>){let(s,q)=qmatch(s,q) { Tri::C => gc, Tri::A => ga, Tri::B => gb };(s,q,z)}

